contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test function: takes depositor address and deposit amount
    // It performs one deposit from this contract to c and then asserts balances reflect increment.
    function run(address depositor, uint256 amount) public payable {
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= amount);
        // Precondition: use the deposit sequence as if depositor is this contract
        // We can only call c methods from this contract; to simulate depositor we require depositor == address(this)
        // so the caller of this test must pass address(this) to represent depositing from this contract
        require(depositor == address(this));

        // read previous balance of this contract in C
        uint256 before = c.balances(address(this));

        // perform the deposit: call Deposit on c, forwarding amount
        c.Deposit{value: amount}();

        // read balance after deposit
        uint256 after = c.balances(address(this));

        // The distinguishing assertion: after == before + amount
        assert(after == before + amount);
    }

    // allow funding this test contract
    receive() external payable {}
}

