contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract: make a deposit and check that recorded balance increased by the deposited amount
    function run(address depositor, uint256 depositAmount) public payable {
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= depositAmount);
        // read old balance
        uint256 oldBal = c.balances(depositor);
        // perform deposit as depositor by using call to c from this contract but specifying msg.sender: we cannot change msg.sender,
        // so we require depositor == address(this) to make the deposit come from this contract.
        require(depositor == address(this));

        // Make the deposit on c forwarding depositAmount
        c.Deposit{value: depositAmount}();

        // read new balance
        uint256 newBal = c.balances(depositor);

        // The invariant: new balance equals old balance plus the deposited amount
        assert(newBal == oldBal + depositAmount);
    }

    // allow funding this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single test function: caller provides two deposit amounts and must send sufficient ether for them.
    // We perform two deposits from this contract to c and assert that c.balances(address(this)) is >= first deposit.
    // On the original contract P (which adds), the balance after the second deposit will be >= first deposit.
    // On mutant M (which overwrites with the second deposit), the balance may be < first deposit if second < first, violating the invariant.
    function runTest(uint firstAmount, uint secondAmount) public payable {
        // must have enough ETH to forward both deposits
        require(msg.value >= firstAmount + secondAmount);

        // First deposit: call c.Deposit with value firstAmount
        c.Deposit{value: firstAmount}();

        // Read balance after first deposit
        uint balAfterFirst = c.balances(address(this));

        // Second deposit: call c.Deposit with value secondAmount
        c.Deposit{value: secondAmount}();

        // Read balance after second deposit
        uint balAfterSecond = c.balances(address(this));

        // The invariant: balance after second deposit must be >= balance after first deposit.
        // This holds for P (because deposits add) but can be violated by M (which overwrites with secondAmount).
        assert(balAfterSecond >= balAfterFirst);
    }

    // Allow contract to receive ETH so it can forward in tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount is the Ether to send in the Deposit call
    function run(address depositor, uint depositAmount) public payable {
        // ensure the test contract has enough Ether to send
        require(address(this).balance >= depositAmount);

        // record previous balance as seen via public getter
        uint prev = c.balances(depositor);

        // perform deposit on behalf of this contract; Deposit uses msg.sender, so
        // to attribute the deposit to "depositor" we must call from that address.
        // Since we cannot change msg.sender here, we instead test the general rule
        // for the caller (this contract). So require depositor == address(this).
        require(depositor == address(this));

        // make the deposit (sends Ether from this contract)
        c.Deposit{value: depositAmount}();

        // observe resulting balance for this contract
        uint after = c.balances(depositor);

        // Assert that the new balance equals previous plus the deposited amount
        assert(after == prev + depositAmount);
    }

    receive() external payable { }
}

